// swift-tools-version:5.9
// Clipper – native macOS shell over the Rust engine (crates/clipper-ffi).
//
// Layout
//   ClipperCoreFFI   C module: the UniFFI header (generated) + empty shim.
//   ClipperCore      Swift bindings (generated by `cargo run -p uniffi-bindgen`).
//   Clipper          The app: AppKit status item + panel, SwiftUI content.
//
// `scripts/build-macos.sh` builds the Rust static library into
// `macos/Libs/libclipper_ffi.a`, regenerates the two generated files and then
// runs `swift build`. Run that script – not a bare `swift build` – after
// changing anything in crates/.
import PackageDescription

let package = Package(
    name: "Clipper",
    defaultLocalization: "en",
    platforms: [.macOS(.v14)],
    products: [
        .executable(name: "Clipper", targets: ["Clipper"]),
    ],
    dependencies: [
        // Global hotkey + native recorder control (the same library Maccy uses).
        // Pinned: 2.3.0 is the newest tag that builds with Xcode 16.0
        // (swift-tools 5.11); 2.4.0 needs tools 6.1 and 3.x needs 6.2.
        .package(url: "https://github.com/sindresorhus/KeyboardShortcuts", exact: "2.3.0"),
    ],
    targets: [
        .target(
            name: "ClipperCoreFFI",
            path: "Sources/ClipperCoreFFI",
            publicHeadersPath: "include"
        ),
        .target(
            name: "ClipperCore",
            dependencies: ["ClipperCoreFFI"],
            path: "Sources/ClipperCore",
            linkerSettings: [
                .unsafeFlags(["-L\(Context.packageDirectory)/Libs"]),
                .linkedLibrary("clipper_ffi"),
            ]
        ),
        .executableTarget(
            name: "Clipper",
            dependencies: [
                "ClipperCore",
                .product(name: "KeyboardShortcuts", package: "KeyboardShortcuts"),
            ],
            path: "Sources/Clipper"
        ),
    ]
)
